 * URI reference parsing, normalization and resolution per RFC 3986,
 * following the simplified generic-syntax rules laid out in the task
 * specification.
 */

export class PercentError extends Error {
  constructor(component) {
    super(`truncated percent-encoding in ${component}`)
    this.component = component
  }
}

const HEX_RE = /[0-9A-Fa-f]/

function isHex(ch) {
  return HEX_RE.test(ch)
}

function isUnreservedByte(code) {
  return (
    (code >= 0x41 && code <= 0x5a) || // A-Z
    (code >= 0x61 && code <= 0x7a) || // a-z
    (code >= 0x30 && code <= 0x39) || // 0-9
    code === 0x2d || // -
    code === 0x2e || // .
    code === 0x5f || // _
    code === 0x7e // ~
  )
}

/**
 * Parse a URI reference into { scheme, authority, path, query, fragment }.
 * Absent components are `null`; present-but-empty ones are `''`.
 * `authority` is the raw (unsplit) authority string, or null when absent.
 */
export function parseRef(s) {
  let rest = s
  let scheme = null

  const colonIdx = rest.indexOf(':')
  if (colonIdx !== -1) {
    const before = rest.slice(0, colonIdx)
    if (!/[/?#]/.test(before)) {
      scheme = before
      rest = rest.slice(colonIdx + 1)
    }
  }

  let authority = null
  if (rest.startsWith('//')) {
    const rem = rest.slice(2)
    const m = rem.search(/[/?#]/)
    if (m === -1) {
      authority = rem
      rest = ''
    } else {
      authority = rem.slice(0, m)
      rest = rem.slice(m)
    }
  }

  let pathEnd = rest.length
  const qIdx = rest.indexOf('?')
  const hIdx = rest.indexOf('#')
  if (qIdx !== -1 && qIdx < pathEnd) pathEnd = qIdx
  if (hIdx !== -1 && hIdx < pathEnd) pathEnd = hIdx

  const path = rest.slice(0, pathEnd)
  let remainder = rest.slice(pathEnd)

  let query = null
  if (remainder.startsWith('?')) {
    const h2 = remainder.indexOf('#')
    if (h2 === -1) {
      query = remainder.slice(1)
      remainder = ''
    } else {
      query = remainder.slice(1, h2)
      remainder = remainder.slice(h2)
    }
  }

  let fragment = null
  if (remainder.startsWith('#')) {
    fragment = remainder.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/**
 * Split a raw authority string into { userinfo, host, port }.
 * `userinfo` and `port` are `null` when absent.
 */
export function parseAuthority(a) {
  let userinfo = null
  let hostport = a
  const atIdx = a.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = a.slice(0, atIdx)
    hostport = a.slice(atIdx + 1)
  }

  const bracketIdx = hostport.lastIndexOf(']')
  const searchFrom = bracketIdx === -1 ? 0 : bracketIdx
  const colonIdx = hostport.indexOf(':', searchFrom)

  let host, port
  if (colonIdx !== -1) {
    host = hostport.slice(0, colonIdx)
    port = hostport.slice(colonIdx + 1)
  } else {
    host = hostport
    port = null
  }
  return { userinfo, host, port }
}

/** Uppercase %XX digits, decoding unreserved bytes. Throws PercentError. */
function normalizePercent(s, component) {
  let out = ''
  for (let i = 0; i < s.length; i++) {
    const c = s[i]
    if (c === '%') {
      if (i + 2 >= s.length || !isHex(s[i + 1]) || !isHex(s[i + 2])) {
        throw new PercentError(component)
      }
      const hex = s.slice(i + 1, i + 3).toUpperCase()
      const code = parseInt(hex, 16)
      if (isUnreservedByte(code)) {
        out += String.fromCharCode(code)
      } else {
        out += '%' + hex
      }
      i += 2
    } else {
      out += c
    }
  }
  return out
}

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21',
}

/** Remove dot segments from a path per RFC 3986 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '/..') {
      input = '/'
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const m = input.match(/^\/?[^/]*/)
      const seg = m[0]
      input = input.slice(seg.length)
      output += seg
    }
  }
  return output
}

function lowerAscii(s) {
  let out = ''
  for (const ch of s) {
    const code = ch.codePointAt(0)
    if (code >= 0x41 && code <= 0x5a) {
      out += String.fromCharCode(code + 0x20)
    } else {
      out += ch
    }
  }
  return out
}

/**
 * Normalize a parsed URI object and serialize it to a string.
 * `parsed` is { scheme, authority, path, query, fragment } as from parseRef.
 * Throws PercentError on a truncated percent-encoding.
 */
export function normalizeParsed(parsed) {
  let { scheme, authority, path, query, fragment } = parsed

  if (scheme !== null) {
    scheme = lowerAscii(scheme)
  }

  let userinfo = null
  let host = null
  let port = null
  if (authority !== null) {
    const a = parseAuthority(authority)
    userinfo = a.userinfo
    host = a.host
    port = a.port
  }

  // Percent-normalize in the order: path, userinfo, host, query, fragment.
  path = normalizePercent(path, 'path')
  if (userinfo !== null) userinfo = normalizePercent(userinfo, 'userinfo')
  if (host !== null) host = normalizePercent(host, 'host')
  if (query !== null) query = normalizePercent(query, 'query')
  if (fragment !== null) fragment = normalizePercent(fragment, 'fragment')

  if (host !== null) {
    host = lowerAscii(host)
  }

  if (port !== null) {
    const defaultPort = scheme !== null ? DEFAULT_PORTS[scheme] : undefined
    if (port === '' || (defaultPort !== undefined && port === defaultPort)) {
      port = null
    }
  }

  path = removeDotSegments(path)

  if (authority !== null && path === '') {
    path = '/'
  }

  let result = ''
  if (scheme !== null) result += scheme + ':'
  if (authority !== null) {
    let rebuiltAuthority = ''
    if (userinfo !== null) rebuiltAuthority += userinfo + '@'
    rebuiltAuthority += host
    if (port !== null) rebuiltAuthority += ':' + port
    result += '//' + rebuiltAuthority
  }
  result += path
  if (query !== null) result += '?' + query
  if (fragment !== null) result += '#' + fragment

  return result
}

function merge(base, refPath) {
  if (base.authority !== null && base.path === '') {
    return '/' + refPath
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/**
 * Resolve a reference against a base per RFC 3986 5.2.2 (strict).
 * Both arguments are parsed objects from parseRef. Returns a parsed
 * (unnormalized) target object.
 */
export function resolveParsed(base, ref) {
  const target = { scheme: null, authority: null, path: '', query: null, fragment: null }

  if (ref.scheme !== null) {
    target.scheme = ref.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else {
    if (ref.authority !== null) {
      target.authority = ref.authority
      target.path = removeDotSegments(ref.path)
      target.query = ref.query
    } else {
      if (ref.path === '') {
        target.path = base.path
        target.query = ref.query !== null ? ref.query : base.query
      } else {
        if (ref.path.startsWith('/')) {
          target.path = removeDotSegments(ref.path)
        } else {
          target.path = removeDotSegments(merge(base, ref.path))
        }
        target.query = ref.query
      }
      target.authority = base.authority
    }
    target.scheme = base.scheme
  }
  target.fragment = ref.fragment

  return target
}
"}

