  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('fs')
  let bytesRead
  while (true) {
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EOF') break
      throw e
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = readStdin()
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const results = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i]
    try {
      if (mode === 'normalize') {
        const parsed = parseRef(line)
        results.push(normalizeParsed(parsed))
      } else {
        const spaceIdx = line.indexOf(' ')
        if (spaceIdx === -1) {
          process.stderr.write(`error: line ${n}: expected a base and a reference\n`)
          process.exit(2)
        }
        const baseStr = line.slice(0, spaceIdx)
        const refStr = line.slice(spaceIdx + 1)
        const base = parseRef(baseStr)
        if (base.scheme === null) {
          process.stderr.write(`error: line ${n}: the base has no scheme\n`)
          process.exit(2)
        }
        const ref = parseRef(refStr)
        const target = resolveParsed(base, ref)
        results.push(normalizeParsed(target))
      }
    } catch (e) {
      if (e instanceof PercentError) {
        process.stderr.write(`error: line ${n}: the ${e.component} has a truncated percent-encoding\n`)
        process.exit(2)
      }
      throw e
    }
  }

  let out = results.map((r) => r + '\n').join('')
  process.stdout.write(out)
  process.exit(0)
}

main()
